// lib/audioTime.ts — real time estimates from the narration lengths.
//
// Reads lib/audioDurations.ts (generated by scripts/build-audio-durations.mjs)
// at build time; nothing here calls the network. A block with no entry there has
// no audio, so it gets no time label at all.
import { AUDIO_DURATIONS } from './audioDurations'

/** A block's narration length in whole minutes (nearest minute, at least 1), or null if it has no audio. */
export function blockMinutes(blockId: string): number | null {
  const seconds = AUDIO_DURATIONS[blockId]
  return seconds ? Math.max(1, Math.round(seconds / 60)) : null
}

/**
 * Total narration seconds for a tier's blocks, or null unless every block has
 * audio (a partial sum would understate how long the tier takes).
 */
export function tierSeconds(blockIds: string[]): number | null {
  if (blockIds.length === 0 || blockIds.some((id) => !AUDIO_DURATIONS[id])) return null
  return blockIds.reduce((n, id) => n + AUDIO_DURATIONS[id], 0)
}

/**
 * Hub tier total. Under an hour: "About N min", to the nearest 5 minutes.
 * An hour or more: "About N hrs", to the nearest half hour ("About 1.5 hrs").
 * `spoken` is the screen-reader wording.
 */
export function tierTotalLabel(seconds: number): { text: string; spoken: string } {
  const minutes = seconds / 60
  if (minutes < 60) {
    const n = Math.max(5, Math.round(minutes / 5) * 5)
    return { text: `About ${n} min`, spoken: `about ${n} minutes` }
  }
  const hours = Math.round(minutes / 30) / 2
  return hours === 1
    ? { text: 'About 1 hr', spoken: 'about 1 hour' }
    : { text: `About ${hours} hrs`, spoken: `about ${hours} hours` }
}

/** True for an authored reading estimate such as "~3 min read" (the Orientation time slot). */
export function isReadingEstimate(timeRange: string): boolean {
  return /min read$/i.test(timeRange.trim())
}
